<script setup lang="ts">
import Button from 'primevue/button';import Column from 'primevue/column';import DataTable from 'primevue/datatable';import Dialog from 'primevue/dialog';import {reactive,ref} from 'vue';import {z} from 'zod';import {useToast} from 'primevue/usetoast';import AppPageHeader from '@/components/app/AppPageHeader.vue';import AppLoadingState from '@/components/state/AppLoadingState.vue';import AppEmptyState from '@/components/state/AppEmptyState.vue';import AppErrorState from '@/components/state/AppErrorState.vue';import {createEmployee,listEmployees,setEmployeeStatus,updateEmployee,type Employee} from '@/modules/employees/employees.service';import {getUserFriendlyApiError} from '@/services/api-errors'
const toast=useToast(),items=ref<Employee[]>([]),loading=ref(false),error=ref<string|null>(null),visible=ref(false),saving=ref(false),selected=ref<Employee|null>(null),statusTarget=ref<Employee|null>(null),formError=ref('');const form=reactive({employeeCode:'',firstName:'',lastName:'',hireDate:new Date().toISOString().slice(0,10)});const schema=z.object({employeeCode:z.string().trim().min(1,'Ingresa el código.'),firstName:z.string().trim().min(1,'Ingresa el nombre.'),lastName:z.string().trim().min(1,'Ingresa el apellido.'),hireDate:z.string().min(1,'Ingresa la fecha de ingreso.')})
async function load(){loading.value=true;try{items.value=await listEmployees();error.value=null}catch(e){error.value=getUserFriendlyApiError(e)}finally{loading.value=false}}function openCreate(){selected.value=null;Object.assign(form,{employeeCode:'',firstName:'',lastName:'',hireDate:new Date().toISOString().slice(0,10)});visible.value=true}function edit(x:Employee){selected.value=x;Object.assign(form,{employeeCode:x.employeeCode,firstName:x.firstName,lastName:x.lastName,hireDate:x.hireDate});visible.value=true}async function save(){const v=schema.safeParse(form);if(!v.success){formError.value=v.error.issues[0]?.message??'';return}saving.value=true;try{if(selected.value)await updateEmployee(selected.value.id,{...form,version:selected.value.version});else await createEmployee(form);visible.value=false;toast.add({severity:'success',summary:'Listo',detail:selected.value?'Cambios guardados.':'Empleado registrado correctamente.',life:3000});await load()}catch(e){formError.value=getUserFriendlyApiError(e)}finally{saving.value=false}}async function changeStatus(){if(!statusTarget.value)return;const e=statusTarget.value;await setEmployeeStatus(e.id,!e.isActive,e.isActive?new Date().toISOString().slice(0,10):null,e.version);statusTarget.value=null;await load()}void load()
</script>
<template><section><AppPageHeader title="Empleados" description="Gestiona la información básica de los empleados." action-label="Registrar empleado" action-icon="pi pi-plus" @action="openCreate"/><AppLoadingState v-if="loading" label="Cargando empleados..."/><AppErrorState v-else-if="error" title="No pudimos cargar los empleados." :description="error" @retry="load"/><AppEmptyState v-else-if="!items.length" title="No hay empleados registrados." description="Registra el primer empleado." action-label="Registrar empleado" @action="openCreate"/><div v-else class="absence-list"><DataTable :value="items" class="absence-table"><Column header="Código" field="employeeCode"/><Column header="Nombre completo"><template #body="{data}">{{data.firstName}} {{data.lastName}}</template></Column><Column header="Estado"><template #body="{data}">{{data.isActive?'Activo':'Inactivo'}}</template></Column><Column header="Ingreso" field="hireDate"/><Column header="Cese"><template #body="{data}">{{data.terminationDate??'—'}}</template></Column><Column header="Acciones"><template #body="{data}"><Button label="Editar" text @click="edit(data)"/><Button :label="data.isActive?'Desactivar':'Activar'" text @click="statusTarget=data"/></template></Column></DataTable><div class="absence-cards"><article v-for="e in items" :key="e.id" class="app-surface absence-card"><strong>{{e.firstName}} {{e.lastName}}</strong><span>Código: {{e.employeeCode}}</span><span>Estado: {{e.isActive?'Activo':'Inactivo'}}</span><span>Ingreso: {{e.hireDate}}</span><span v-if="e.terminationDate">Cese: {{e.terminationDate}}</span><div class="absence-card__actions"><Button label="Editar" text @click="edit(e)"/><Button :label="e.isActive?'Desactivar':'Activar'" text @click="statusTarget=e"/></div></article></div></div><Dialog :visible="visible" modal class="app-form-dialog" :header="selected?'Editar empleado':'Registrar empleado'" @update:visible="visible=false"><form class="absence-form" @submit.prevent="save"><label>Código<input v-model="form.employeeCode"/></label><label>Nombres<input v-model="form.firstName"/></label><label>Apellidos<input v-model="form.lastName"/></label><label>Fecha de ingreso<input v-model="form.hireDate" type="date"/></label><p v-if="formError">{{formError}}</p><div class="absence-card__actions"><Button label="Cancelar" text type="button" @click="visible=false"/><Button :label="selected?'Guardar cambios':'Registrar empleado'" type="submit" :loading="saving"/></div></form></Dialog><Dialog :visible="Boolean(statusTarget)" modal class="app-form-dialog" header="Cambiar estado" @update:visible="statusTarget=null"><p>Se actualizará el estado del empleado.</p><template #footer><Button label="Volver" text @click="statusTarget=null"/><Button :label="statusTarget?.isActive?'Desactivar':'Activar'" @click="changeStatus"/></template></Dialog></section></template>
